// TH16 v1.00a Stage 5 midboss-wave card th16_s5_w05.
// Source: st05.ecl.txt MainSub04:1243-1254 (one Phantom02R every 10 frames, 40 total),
// Phantom02R:1518-1529 -> Phantom02:1486-1505 (movement + async emit task),
// Phantom02_at:1531-1561 (per-rank interval, aimed shot with RANDF2*30deg spread).

const TIME_LIMIT: int = 774;
const OPENING_BUFFER: int = 120;

// TH16 type 7 = etSprite(0, 7, 2); approved alias of the identical TH18 slot.
const TH16_RING_BALL2: int = 464;
const BULLET_COLOR: int = 2;

// Source bullet EX list: ANIM(a=1, birth animation omitted; its -4*velocity
// spawn shift is applied at fire time), WAIT(60), ACCEL(r=0.02, a=200).
xformdef PHANTOM_BULLET {
    @60 add_speed(0fx);
    @200 set_accel(0.02fx);
    set_accel(0fx);
}

// Phantom02_at: one fixed-direction shot per trigger at ANGLE_PLAYER +
// RANDF2*30deg, 1000 triggers; interval is the source per-rank wait.
async sub phantom_shot() {
    var interval: int = 50;
    var rk: int = global(GVAR_RANK);
    if rk == 1 { interval = 20; }
    if rk == 2 { interval = 13; }
    if rk == 3 { interval = 10; }
    var left: int = 1000;
    loop {
        wait(interval);
        var u: int = rand(65536) - 32768;
        var spread: int = (5461fx * ((u as fx) / 32768)) as int;
        var dir: angle = aim_player() + (spread as angle);
        // ANIM a=1 birth shift: position -= 4*velocity (0.5 px/frame).
        var bx: fx = $self_x - 2fx * cos(dir);
        var by: fx = $self_y - 2fx * sin(dir);
        _ = fire(TH16_RING_BALL2, BULLET_COLOR, bx, by, 0.5fx, dir, PHANTOM_BULLET, none);
        left = left - 1;
        if left <= 0 { break; }
    }
}

// Phantom02: frames, absolute+relative movement, and the emit task kickoff.
async sub phantom02() {
    set_invuln(65535);
    set_hurtbox(14fx); // setHurtbox(28,28): source radius 28*0.5
    set_hitbox(8fx);   // setHitbox(16,16): source radius 16*0.5

    // getAngle(A, FINAL_X, FINAL_Y, 0, -300); moveVel(A, -0.5);
    // moveVelTime(120, 3, A, -1.0); moveEllipseRel(F0, 0.034906585, 10, 0, ABS_ANGLE, 0)
    var abs_a: angle = atan2(-300fx - $self_y, 0fx - $self_x);
    var ax: fx = $self_x;
    var ay: fx = $self_y;
    var th: int = 0; // F0 inherited phase, initial slot value 0
    var k: int = 0;

    // moveEllipseRel composes REL(theta0) at the setter itself.
    var s0: fx = 10fx * sin((th - (abs_a as int)) as angle);
    move_to(0, ax - s0 * sin(abs_a), ay + s0 * cos(abs_a), EASE_LINEAR);

    spawn phantom_shot();
    loop {
        wait(1);
        k = k + 1;
        var t: int = k;
        if t > 120 { t = 120; }
        var u: fx = (t as fx) / 120fx;
        var q: fx = u * u * u * u; // moveVelTime mode 3 = quart-in
        var spd: fx = -0.5fx - 0.5fx * q;
        ax = ax + spd * cos(abs_a);
        ay = ay + spd * sin(abs_a);
        th = (k * 3641) / 10; // 0.034906585 rad/frame
        var s: fx = 10fx * sin((th - (abs_a as int)) as angle);
        move_to(0, ax - s * sin(abs_a), ay + s * cos(abs_a), EASE_LINEAR);
    }
}

// MainSub04: $A = 40; spawn, wait 10, test-and-decrement.
async sub pattern() {
    wait(OPENING_BUFFER);
    var left: int = 40;
    loop {
        var u: int = rand(65536) - 32768;
        var x: fx = (u as fx) / 32768 * 120fx; // RANDF2 * 120
        _ = spawn_enemy(x, -16fx, 210, 0, 0, 0, phantom02);
        wait(10);
        left = left - 1;
        if left <= 0 { break; }
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
